  const app = require('../index.js');
  expect(app).toBeDefined();
});
JS
fi
# run tests with isolated env, prefer local npm scripts
NODE_ENV=test npm test --silent || { echo 'ERROR: tests failed' >&2; exit 3; }
printf "ok\n"

